// ── Explorer: selectable branches, loaded on demand ─────────────────────────────────────
// A fictional settings store. Keys load when opened (600 ms), Fonts pages ten at a time,
// Archive fails on its first load, and Empty shelf turns out to have no subkeys.
const STORE_ROOTS: TreeNode[] = [
  { id: "studio", label: "Studio", hasChildren: true },
  { id: "workspace", label: "Workspace", hasChildren: true },
  { id: "archive", label: "Archive", hasChildren: true },
  { id: "shelf", label: "Empty shelf", hasChildren: true },
];
const FONT_NAMES = [
  "Atlas",
  "Birch",
  "Cobalt",
  "Dune",
  "Ember",
  "Fjord",
  "Garnet",
  "Harbor",
  "Iris",
  "Juniper",
  "Kestrel",
  "Linen",
  "Meadow",
  "Nimbus",
  "Orchid",
  "Pebble",
  "Quill",
  "Rowan",
  "Sable",
  "Tundra",
  "Umber",
  "Vellum",
  "Willow",
  "Yarrow",
  "Zephyr",
];

function subkeys(id: string): TreeNode[] {
  const leaf = (key: string, label: string): TreeNode => ({
    id: `${id}/${key}`,
    label,
    hasChildren: false,
  });
  const branch = (key: string, label: string): TreeNode => ({
    id: `${id}/${key}`,
    label,
    hasChildren: true,
  });
  if (id === "studio")
    return [
      branch("fonts", "Fonts"),
      branch("colours", "Colours"),
      leaf("name", "Display name"),
      leaf("zone", "Time zone"),
    ];
  if (id === "workspace")
    return [branch("layout", "Layout"), leaf("theme", "Theme"), leaf("density", "Density")];
  if (id === "archive") return [leaf("retention", "Retention"), leaf("location", "Location")];
  if (id === "studio/fonts") return FONT_NAMES.map((name) => leaf(name.toLowerCase(), name));
  if (id === "studio/colours")
    return ["Accent", "Canvas", "Surface"].map((name) => leaf(name.toLowerCase(), name));
  if (id === "workspace/layout")
    return [leaf("drawer", "Drawer width"), leaf("inspector", "Inspector width")];
  return [];
}

const PAGE = 10;
const later = (run: () => void, fail = false) =>
  new Promise<void>((resolve, reject) =>
    setTimeout(() => {
      if (fail) return reject(new Error("The store did not answer"));
      run();
      resolve();
    }, 600),
  );

function patchNode(list: TreeNode[], id: string, update: (node: TreeNode) => TreeNode): TreeNode[] {
  return list.map((node) =>
    node.id === id
      ? update(node)
      : node.children
        ? { ...node, children: patchNode(node.children, id, update) }
        : node,
  );
}

function ExplorerTree() {
  const [nodes, setNodes] = useState(STORE_ROOTS);
  const [selected, setSelected] = useState<string | null>(null);
  const failed = useRef(new Set<string>());
  const loadChildren = (node: TreeNode) => {
    const fail = node.id === "archive" && !failed.current.has(node.id);
    if (fail) failed.current.add(node.id);
    return later(() => {
      const all = subkeys(node.id);
      setNodes((list) =>
        patchNode(list, node.id, (current) => ({
          ...current,
          children: all.slice(0, PAGE),
          hasMore: all.length > PAGE,
        })),
      );
    }, fail);
  };
  const loadMore = (node: TreeNode) =>
    later(() => {
      const all = subkeys(node.id);
      setNodes((list) =>
        patchNode(list, node.id, (current) => {
          const count = (current.children?.length ?? 0) + PAGE;
          return { ...current, children: all.slice(0, count), hasMore: all.length > count };
        }),
      );
    });
  return (
    <div className="flex w-72 max-w-full flex-col gap-2">
      <div className="h-90" data-testid="tree-explorer">
        <Tree
          nodes={nodes}
          aria-label="Settings keys"
          selectableGroups
          selectedId={selected}
          onSelectedIdChange={setSelected}
          onLoadChildren={loadChildren}
          onLoadMore={loadMore}
        />
      </div>
      <p className="type-caption text-fg-muted" aria-live="polite">
        {selected ? `Selected: ${selected.split("/").join(" › ")}` : "No key selected"}
      </p>
    </div>
  );
}

// ── Project files: every addition together, in a fixed state ────────────────────────────
const PROJECT: TreeNode[] = [
  {
    id: "brief",
    label: "Brief",
    children: [
      { id: "brief/scope", label: "scope.md" },
      { id: "brief/budget", label: "budget.xlsx" },
      { id: "brief/timeline", label: "timeline.md", renamable: false },
    ],
  },
  {
    id: "surveys",
    label: "Surveys",
    children: [
      { id: "surveys/north", label: "north-shore.pdf" },
      { id: "surveys/south", label: "south-shore.pdf" },
    ],
  },
  { id: "locked", label: "Signed contract.pdf", movable: false },
  { id: "notes", label: "notes.md" },
];
const SIZES: Record<string, string> = {
  "brief/scope": "4 KB",
  "brief/budget": "86 KB",
  "surveys/north": "2.1 MB",
  "surveys/south": "1.9 MB",
  notes: "1 KB",
};

function ProjectTree() {
  const [nodes, setNodes] = useState(PROJECT);
  const [selected, setSelected] = useState<string[]>(["brief/budget"]);
  const [log, setLog] = useState("No change yet");
  const tree = useRef<TreeHandle>(null);
  const rename = (id: string, label: string) => {
    if (label.includes("/")) return "A name can't contain a slash";
    setNodes((list) => patchNode(list, id, (node) => ({ ...node, label })));
    setLog(`Renamed to ${label}`);
    return undefined;
  };
  const move = (next: TreeMove) => {
    setNodes((list) => moveTreeNodes(list, next));
    setLog(
      `${next.ids.join(", ")} to ${next.parentId ?? "top level"} at ${next.index} by ${next.input}`,
    );
  };
  return (
    <div className="flex w-96 max-w-full flex-col gap-2" data-testid="tree-project">
      <div className="h-90">
        <Tree
          ref={tree}
          nodes={nodes}
          aria-label="Project files"
          defaultExpanded={["brief", "surveys"]}
          selectionMode="multiple"
          selectedIds={selected}
          onSelectedIdsChange={setSelected}
          selectionLimit={6}
          selectableGroups
          checkboxes
          onRename={rename}
          onMove={move}
          canMove={(next) =>
            next.parentId === "locked" ? "Signed contract.pdf isn't a folder" : true
          }
          renderTrailing={(node) => SIZES[node.id] ?? null}
          rowWrapper={(node, row) => (
            <ContextMenu.Root>
              <ContextMenu.Trigger render={row} />
              <ContextMenu.Popup aria-label={`Actions for ${node.label}`}>
                <Menu.Item onClick={() => void tree.current?.rename(node.id)}>Rename</Menu.Item>
                <TreeMoveItems tree={tree} id={node.id} />
              </ContextMenu.Popup>
            </ContextMenu.Root>
          )}
        />
      </div>
      <p className="type-caption text-fg-muted" data-testid="tree-project-log">
        {log}
      </p>
      <p className="type-caption text-fg-muted" data-testid="tree-project-selected">
        {selected.join(", ") || "Nothing selected"}
      </p>
    </div>
  );
}

function RevealTree() {
  const [nodes, setNodes] = useState(STORE_ROOTS);
  const [result, setResult] = useState("Not revealed yet");
  const tree = useRef<TreeHandle>(null);
  const loadChildren = (node: TreeNode) =>
    later(() => {
      const all = subkeys(node.id);
      setNodes((list) =>
        patchNode(list, node.id, (current) => ({
          ...current,
          children: all.slice(0, PAGE),
          hasMore: all.length > PAGE,
        })),
      );
    });
  const loadMore = (node: TreeNode) =>
    later(() => {
      const all = subkeys(node.id);
      setNodes((list) =>
        patchNode(list, node.id, (current) => {
          const count = (current.children?.length ?? 0) + PAGE;
          return { ...current, children: all.slice(0, count), hasMore: all.length > count };
        }),
      );
    });
  return (
    <div className="flex w-72 max-w-full flex-col gap-2" data-testid="tree-reveal">
      <Button
        onClick={() => {
          setResult("Looking…");
          void tree.current
            ?.reveal("studio/fonts/zephyr", { path: ["studio", "studio/fonts"], focus: true })
            .then((found) => setResult(found ? "Found Zephyr" : "Not found"));
        }}
      >
        Reveal Zephyr
      </Button>
      <div className="h-80">
        <Tree
          ref={tree}
          nodes={nodes}
          aria-label="Settings store"
          selectableGroups
          onLoadChildren={loadChildren}
          onLoadMore={loadMore}
        />
      </div>
      <p className="type-caption text-fg-muted" data-testid="tree-reveal-result" aria-live="polite">
        {result}
      </p>
    </div>
  );
}

